using Microsoft.Extensions.Logging;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using Yubico.YubiKit.Core;
using Yubico.YubiKit.Core.Credentials;
using Yubico.YubiKit.Core.Devices;
using Yubico.YubiKit.Core.Protocols.Otp.Hid;

namespace Yubico.YubiKit.YubiOtp.Backend;

/// <summary>
/// Backend implementation for YubiOTP operations over OTP HID (8-byte feature reports).
/// Delegates to <see cref="IOtpHidProtocol"/>. Data reads require the expected prefix plus two CRC bytes
/// and validate that prefix; excess bytes are not returned. Writes check minimum status length here,
/// not the data-response CRC. CRC detects transmission errors, not cryptographic authenticity.
/// </summary>
internal sealed class HidBackend : IYubiOtpBackend
{
    private static readonly ILogger Logger =
        YubiKitLogging.LoggerFactory.CreateLogger<HidBackend>();

    private readonly IOtpHidProtocol _protocol;

    public HidBackend(IOtpHidProtocol protocol)
    {
        ArgumentNullException.ThrowIfNull(protocol);
        _protocol = protocol;
    }

    public static async ValueTask<YubiOtpInitialization> ReadInitialStateAsync(
        IOtpHidProtocol protocol,
        CancellationToken cancellationToken)
    {
        var status = await protocol.ReadStatusAsync(cancellationToken).ConfigureAwait(false);
        var firmwareVersion = protocol.FirmwareVersion
                              ?? new FirmwareVersion(status.Span[0], status.Span[1], status.Span[2]);

        return new YubiOtpInitialization(firmwareVersion, status);
    }

    public async ValueTask<ReadOnlyMemory<byte>> WriteUpdateAsync(
        ConfigSlot slot,
        ReadOnlyMemory<byte> data,
        CancellationToken cancellationToken)
    {
        Logger.LogDebug("HidBackend WriteUpdate: slot={Slot}", slot);

        var response = await _protocol.SendAndReceiveAsync((byte)slot, data, cancellationToken)
            .ConfigureAwait(false);

        if (response.Length < YubiOtpConstants.StatusBytesLength)
        {
            throw new BadResponseException(
                $"WriteUpdate response too short. Expected at least {YubiOtpConstants.StatusBytesLength} bytes, got {response.Length}.");
        }

        return response;
    }

    public async ValueTask<ReadOnlyMemory<byte>> SendAndReceiveAsync(
        ConfigSlot slot,
        ReadOnlyMemory<byte> data,
        int expectedLength,
        UserPresenceNotification userPresenceNotification,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(userPresenceNotification);

        Logger.LogDebug("HidBackend SendAndReceive: slot={Slot}, expectedLength={Length}", slot, expectedLength);

        Exception? primaryException = null;
        var outcome = UserPresenceOutcome.Failed;
        ReadOnlyMemory<byte> response = default;
        var responseTransferred = false;
        try
        {
            response = await _protocol.SendAndReceiveAsync(
                    (byte)slot,
                    data,
                    userPresenceNotification,
                    cancellationToken)
                .ConfigureAwait(false);

            // CRC validation: response contains [data...][crc_lo][crc_hi]
            var totalLength = expectedLength + 2;
            if (response.Length < totalLength)
            {
                throw new BadResponseException(
                    $"Response too short for CRC validation. Expected at least {totalLength} bytes, got {response.Length}.");
            }

            if (!ChecksumUtils.CheckCrc(response.Span, totalLength))
            {
                throw new BadResponseException("Invalid CRC in OTP HID response.");
            }

            outcome = UserPresenceOutcome.Completed;
            await userPresenceNotification.ResolveAsync(outcome).ConfigureAwait(false);
            responseTransferred = true;
            return response[..expectedLength];
        }
        catch (OperationCanceledException ex) when (cancellationToken.IsCancellationRequested)
        {
            outcome = UserPresenceOutcome.Cancelled;
            primaryException = ex;
            throw;
        }
        catch (OtpHidTouchTimeoutException ex)
        {
            outcome = UserPresenceOutcome.TimedOut;
            primaryException = ex;
            throw;
        }
        catch (Exception ex)
        {
            primaryException = ex;
            throw;
        }
        finally
        {
            await userPresenceNotification.ResolveAsync(outcome, primaryException).ConfigureAwait(false);
            if (!responseTransferred && !response.IsEmpty)
            {
                CryptographicOperations.ZeroMemory(MemoryMarshal.AsMemory(response).Span);
            }
        }
    }
}

