namespace Yubico.YubiKit.YubiOtp;

/// <summary>
/// Ticket flags (TKTFLAG) controlling OTP ticket generation behavior.
/// </summary>
/// <remarks>
/// Keyboard flags and their legacy delay behavior depend on mode/firmware. Use a mode-specific builder;
/// combining raw flag names does not establish a supported device configuration.
/// </remarks>
[Flags]
public enum TicketFlag : byte
{
    None = 0x00,
    TabFirst = 0x01,
    AppendTab1 = 0x02,
    AppendTab2 = 0x04,
    AppendDelay1 = 0x08,
    AppendDelay2 = 0x10,
    AppendCr = 0x20,

    /// <summary>
    ///     OATH-HOTP mode. Shares bit 0x40 with <see cref="ChalResp" />; the configuration flags decide
    ///     which mode the slot is in.
    /// </summary>
    OathHotp = 0x40,

    /// <summary>
    ///     Challenge-response mode. Shares bit 0x40 with <see cref="OathHotp" />.
    /// </summary>
    ChalResp = 0x40,

    /// <summary>
    ///     Set on slot 1: the YubiKey refuses to write slot 2 unless slot 2 is already configured with
    ///     this flag too. Not part of the update mask.
    /// </summary>
    ProtectSlot2 = 0x80
}

/// <summary>
/// Defines which <see cref="TicketFlag"/> values are valid for update operations.
/// </summary>
public static class TicketFlagMasks
{
    public const TicketFlag UpdateMask =
        TicketFlag.TabFirst |
        TicketFlag.AppendTab1 |
        TicketFlag.AppendTab2 |
        TicketFlag.AppendDelay1 |
        TicketFlag.AppendDelay2 |
        TicketFlag.AppendCr;
}

