using NSubstitute;
using Yubico.YubiKit.Core;
using Yubico.YubiKit.Core.Credentials;
using Yubico.YubiKit.Core.Devices;
using Yubico.YubiKit.Core.Protocols.SmartCard.Apdu;
using Yubico.YubiKit.YubiOtp.Backend;

namespace Yubico.YubiKit.YubiOtp.UnitTests;

public class SmartCardBackendTests
{
    private readonly ISmartCardProtocol _protocol = Substitute.For<ISmartCardProtocol>();

    private SmartCardBackend CreateBackend(
        FirmwareVersion? version = null,
        byte initialProgSeq = 0) =>
        new(_protocol, version ?? new FirmwareVersion(5, 7, 0), initialProgSeq);

    private static ApduResponse MakeStatusResponse(byte progSeq, byte touchLo = 0, byte touchHi = 0)
    {
        // Response data: [fw_major, fw_minor, fw_patch, prog_seq, touch_lo, touch_hi] + SW 9000
        byte[] raw = [5, 7, 0, progSeq, touchLo, touchHi, 0x90, 0x00];
        return new ApduResponse(raw);
    }

    [Fact]
    public async Task ReadInitialStateAsync_MalformedManagementVersion_UsesOtpStatusVersion()
    {
        _protocol.SelectAsync(Arg.Any<ReadOnlyMemory<byte>>(), Arg.Any<CancellationToken>())
            .Returns(
                Task.FromResult<ReadOnlyMemory<byte>>("YubiKey 5.4.x"u8.ToArray()),
                Task.FromResult<ReadOnlyMemory<byte>>(new byte[] { 5, 7, 0, 0, 0, 0 }));

        YubiOtpInitialization initialization = await SmartCardBackend.ReadInitialStateAsync(
            _protocol, TestContext.Current.CancellationToken);

        Assert.Equal(new FirmwareVersion(5, 7, 0), initialization.FirmwareVersion);
    }

    [Fact]
    public async Task WriteUpdateAsync_SendsCorrectApdu()
    {
        byte[] configData = [0x01, 0x02, 0x03];
        var response = MakeStatusResponse(progSeq: 1);

        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));

        var backend = CreateBackend(initialProgSeq: 0);
        await backend.WriteUpdateAsync(ConfigSlot.Config1, configData, CancellationToken.None);

        await _protocol.Received(1).TransmitAndReceiveAsync(
            Arg.Is<ApduCommand>(a =>
                a.Ins == YubiOtpConstants.InsConfig &&
                a.P1 == (byte)ConfigSlot.Config1 &&
                a.P2 == 0),
            Arg.Any<bool>(),
            Arg.Any<CancellationToken>());
    }

    [Fact]
    public async Task WriteUpdateAsync_ReturnsStatusBytes()
    {
        var response = MakeStatusResponse(progSeq: 1, touchLo: 0x03);

        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));

        var backend = CreateBackend(initialProgSeq: 0);
        var result = await backend.WriteUpdateAsync(ConfigSlot.Config1, ReadOnlyMemory<byte>.Empty, CancellationToken.None);

        // Status bytes are the data portion (without SW)
        Assert.Equal(6, result.Length);
        Assert.Equal(0x03, result.Span[4]); // touch_lo
    }

    [Fact]
    public async Task WriteUpdateAsync_ProgSeqNotIncremented_ThrowsInvalidOperation()
    {
        // Initial 3 expects 4; returned 5 is rejected outside the firmware bypass interval.
        var response = MakeStatusResponse(progSeq: 5);

        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));

        var backend = CreateBackend(initialProgSeq: 3);

        await Assert.ThrowsAsync<InvalidOperationException>(
            () => backend.WriteUpdateAsync(ConfigSlot.Config1, ReadOnlyMemory<byte>.Empty, CancellationToken.None).AsTask());
    }

    [Fact]
    public async Task WriteUpdateAsync_ProgSeqRolloverToZero_Succeeds()
    {
        // prog_seq rolling over to 0 is always accepted
        var response = MakeStatusResponse(progSeq: 0);

        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));

        var backend = CreateBackend(initialProgSeq: 255);
        var result = await backend.WriteUpdateAsync(ConfigSlot.Config1, ReadOnlyMemory<byte>.Empty, CancellationToken.None);

        Assert.True(result.Length >= 6);
    }

    [Fact]
    public async Task WriteUpdateAsync_Firmware5x_SkipsProgSeqValidation()
    {
        // The current implementation bypasses 5.0.0 <= version < 5.5.0; this fake exercises 5.2.0.
        var response = MakeStatusResponse(progSeq: 99);

        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));

        var backend = CreateBackend(version: new FirmwareVersion(5, 2, 0), initialProgSeq: 0);

        // Should not throw despite prog_seq mismatch
        var result = await backend.WriteUpdateAsync(ConfigSlot.Config1, ReadOnlyMemory<byte>.Empty, CancellationToken.None);
        Assert.True(result.Length >= 6);
    }

    [Fact]
    public async Task WriteUpdateAsync_EmptyResponse_FallsBackToReadStatus()
    {
        // First call returns empty data (just SW), second call returns full status
        var emptyResponse = new ApduResponse([], 0x9000 - 0x10000);
        var statusResponse = MakeStatusResponse(progSeq: 1);

        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(
                Task.FromResult(emptyResponse),
                Task.FromResult(statusResponse));

        var backend = CreateBackend(initialProgSeq: 0);
        var result = await backend.WriteUpdateAsync(ConfigSlot.Config1, ReadOnlyMemory<byte>.Empty, CancellationToken.None);

        // Should have called TransmitAndReceiveAsync twice (config + status)
        await _protocol.Received(2).TransmitAndReceiveAsync(
            Arg.Any<ApduCommand>(),
            Arg.Any<bool>(),
            Arg.Any<CancellationToken>());
    }

    [Fact]
    public async Task SendAndReceiveAsync_ReturnsExpectedLengthData()
    {
        byte[] responseData = [0x01, 0x02, 0x03, 0x04, 0x90, 0x00];
        var response = new ApduResponse(responseData);

        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));

        var backend = CreateBackend();
        var result = await backend.SendAndReceiveAsync(
            ConfigSlot.DeviceSerial,
            ReadOnlyMemory<byte>.Empty,
            4,
            UserPresenceNotification.None,
            cancellationToken: CancellationToken.None);

        Assert.Equal(4, result.Length);
        Assert.Equal(0x01, result.Span[0]);
        Assert.Equal(new byte[] { 0x01, 0x02, 0x03, 0x04 }, response.Data.ToArray());
    }

    [Fact]
    public async Task SendAndReceiveAsync_ResponseTooShort_ThrowsBadResponse()
    {
        // Only 2 data bytes, but we expect 4
        byte[] responseData = [0x01, 0x02, 0x90, 0x00];
        var response = new ApduResponse(responseData);

        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));

        var backend = CreateBackend();

        await Assert.ThrowsAsync<BadResponseException>(
            () => backend.SendAndReceiveAsync(
                ConfigSlot.DeviceSerial,
                ReadOnlyMemory<byte>.Empty,
                4,
                UserPresenceNotification.None,
                cancellationToken: CancellationToken.None).AsTask());
    }

    [Fact]
    public async Task SendAndReceiveAsync_WhenResolutionThrowsAfterSuccess_PropagatesResolutionException()
    {
        var response = new ApduResponse(new byte[] { 0x01, 0x02, 0x03, 0x04, 0x90, 0x00 });
        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));
        var expected = new InvalidOperationException("resolution failed");
        var backend = CreateBackend();
        UserPresenceNotification notification = UserPresenceNotification.Create(
            new ThrowingPrompt(resolutionException: expected),
            CreateContext());

        InvalidOperationException actual = await Assert.ThrowsAsync<InvalidOperationException>(() =>
            backend.SendAndReceiveAsync(
                ConfigSlot.ChalHmac1,
                ReadOnlyMemory<byte>.Empty,
                4,
                notification,
                TestContext.Current.CancellationToken).AsTask());

        Assert.Same(expected, actual);
        Assert.All(response.Data.ToArray(), value => Assert.Equal(0, value));
    }

    [Fact]
    public async Task SendAndReceiveAsync_WhenTransportTimesOut_ResolvesFailedAndPreservesTimeout()
    {
        var expected = new TimeoutException("Transport timed out.");
        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromException<ApduResponse>(expected));
        var prompt = new ThrowingPrompt();
        var backend = CreateBackend();

        TimeoutException actual = await Assert.ThrowsAsync<TimeoutException>(() => backend.SendAndReceiveAsync(
            ConfigSlot.ChalHmac1,
            ReadOnlyMemory<byte>.Empty,
            4,
            UserPresenceNotification.Create(prompt, CreateContext()),
            TestContext.Current.CancellationToken).AsTask());

        Assert.Same(expected, actual);
        Assert.Equal(UserPresenceOutcome.Failed, Assert.Single(prompt.Outcomes));
    }

    [Fact]
    public async Task SendAndReceiveAsync_WhenOperationAndResolutionThrow_PreservesOperationException()
    {
        var response = new ApduResponse(new byte[] { 0x01, 0x02, 0x90, 0x00 });
        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));
        var backend = CreateBackend();
        UserPresenceNotification notification = UserPresenceNotification.Create(
            new ThrowingPrompt(resolutionException: new InvalidOperationException("resolution failed")),
            CreateContext());

        BadResponseException actual = await Assert.ThrowsAsync<BadResponseException>(() =>
            backend.SendAndReceiveAsync(
                ConfigSlot.ChalHmac1,
                ReadOnlyMemory<byte>.Empty,
                4,
                notification,
                TestContext.Current.CancellationToken).AsTask());

        Assert.Contains("Expected 4 bytes", actual.Message, StringComparison.Ordinal);
    }

    [Fact]
    public async Task SendAndReceiveAsync_WhenRequestThrows_DoesNotTransmitOrResolve()
    {
        var expected = new InvalidOperationException("request failed");
        var prompt = new ThrowingPrompt(requestException: expected);
        var backend = CreateBackend();
        UserPresenceNotification notification = UserPresenceNotification.Create(prompt, CreateContext());

        InvalidOperationException actual = await Assert.ThrowsAsync<InvalidOperationException>(() =>
            backend.SendAndReceiveAsync(
                ConfigSlot.ChalHmac1,
                ReadOnlyMemory<byte>.Empty,
                4,
                notification,
                TestContext.Current.CancellationToken).AsTask());

        Assert.Same(expected, actual);
        Assert.Equal(0, prompt.ResolutionCount);
        await _protocol.DidNotReceive().TransmitAndReceiveAsync(
            Arg.Any<ApduCommand>(),
            Arg.Any<bool>(),
            Arg.Any<CancellationToken>());
    }

    [Fact]
    public async Task SendAndReceiveAsync_SendsCorrectSlotInP1()
    {
        byte[] responseData = new byte[22]; // 20 bytes + SW
        responseData[^2] = 0x90;
        responseData[^1] = 0x00;
        var response = new ApduResponse(responseData);

        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));

        var backend = CreateBackend();
        await backend.SendAndReceiveAsync(
            ConfigSlot.ChalHmac2,
            new byte[64],
            20,
            UserPresenceNotification.None,
            cancellationToken: CancellationToken.None);

        await _protocol.Received(1).TransmitAndReceiveAsync(
            Arg.Is<ApduCommand>(a => a.P1 == (byte)ConfigSlot.ChalHmac2),
            Arg.Any<bool>(),
            Arg.Any<CancellationToken>());
    }

    // Valid-length challenge-response keys must reach the wire unmodified; fake APDUs do not establish
    // real-device SmartCard challenge support.

    [Fact]
    public async Task WriteUpdateAsync_HmacSha1ValidKey_PreservesExactKeyBytesThroughEncoding()
    {
        byte[] hmacKey = Enumerable.Range(1, 20).Select(i => (byte)i).ToArray();
        using var config = new HmacSha1SlotConfiguration(hmacKey);
        byte[] configBytes = config.GetConfig();

        var response = MakeStatusResponse(progSeq: 1);
        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
                Arg.Any<bool>(),
                Arg.Any<CancellationToken>())
            .Returns(Task.FromResult(response));

        var backend = CreateBackend(initialProgSeq: 0);
        await backend.WriteUpdateAsync(ConfigSlot.Config1, configBytes, CancellationToken.None);

        await _protocol.Received(1).TransmitAndReceiveAsync(
            Arg.Is<ApduCommand>(a => a.Data.ToArray().SequenceEqual(configBytes)),
            Arg.Any<bool>(),
            Arg.Any<CancellationToken>());

        // The exact key bytes (not a hash, not padding) must appear at their wire offsets.
        Assert.Equal(hmacKey[..16], configBytes[22..38]);
        Assert.Equal(hmacKey[16..20], configBytes[16..20]);
    }

    private static UserPresenceContext CreateContext() => new()
    {
        Basis = UserPresenceBasis.PolicyRequires,
        Application = "YubiOTP",
        Scope = "One"
    };

    private sealed class ThrowingPrompt(
        Exception? requestException = null,
        Exception? resolutionException = null) : IUserPresencePrompt
    {
        public int ResolutionCount { get; private set; }
        public List<UserPresenceOutcome> Outcomes { get; } = [];

        public ValueTask OnUserPresenceRequestedAsync(
            UserPresenceContext context,
            CancellationToken cancellationToken) => requestException is null
                ? default
                : ValueTask.FromException(requestException);

        public ValueTask OnUserPresenceResolvedAsync(
            UserPresenceContext context,
            UserPresenceOutcome outcome,
            CancellationToken cancellationToken)
        {
            ResolutionCount++;
            Outcomes.Add(outcome);
            return resolutionException is null
                ? default
                : ValueTask.FromException(resolutionException);
        }
    }

    [Fact]
    public async Task WriteUpdateAsync_YubicoOtpChallengeResponseValidKey_PreservesExactKeyBytesThroughEncoding()
    {
        byte[] aesKey = Enumerable.Range(100, 16).Select(i => (byte)i).ToArray();
        using var config = new YubicoOtpChallengeResponseSlotConfiguration(aesKey);
        byte[] configBytes = config.GetConfig();

        var response = MakeStatusResponse(progSeq: 1);
        _protocol.TransmitAndReceiveAsync(
                Arg.Any<ApduCommand>(),
